-- Run this in Supabase SQL Editor after schema.sql.
do $$ declare b uuid; m uuid; begin
  insert into branches(name,code,address,status) values ('MG Road','MG01','MG Road, Bengaluru','ACTIVE') on conflict(code) do update set name=excluded.name returning id into b;
  insert into medicines(name,generic_name,status)
  select v.name,v.generic_name,'ACTIVE' from (values
    ('Augmentin 625mg','Amoxicillin + Clavulanate'),('Pantop 40mg','Pantoprazole'),('Dolo 650mg','Paracetamol'),('Telma 40mg','Telmisartan'),('Azithral 500mg','Azithromycin'),('Shelcal 500mg','Calcium + Vitamin D3')) v(name,generic_name)
  where not exists (select 1 from medicines m where m.name=v.name);
  insert into batches(medicine_id,branch_id,batch_number,expiry_date,purchase_price,mrp,selling_price,received_quantity,available_quantity,status)
  select id,b,'DEMO-'||left(id::text,6),'2027-12-31',case name when 'Augmentin 625mg' then 12.95 when 'Pantop 40mg' then 2.94 when 'Dolo 650mg' then 1.47 when 'Telma 40mg' then 5.46 when 'Azithral 500mg' then 7.84 else 3.78 end,case name when 'Augmentin 625mg' then 18.5 when 'Pantop 40mg' then 4.2 when 'Dolo 650mg' then 2.1 when 'Telma 40mg' then 7.8 when 'Azithral 500mg' then 11.2 else 5.4 end,case name when 'Augmentin 625mg' then 18.5 when 'Pantop 40mg' then 4.2 when 'Dolo 650mg' then 2.1 when 'Telma 40mg' then 7.8 when 'Azithral 500mg' then 11.2 else 5.4 end,case name when 'Augmentin 625mg' then 24 when 'Pantop 40mg' then 86 when 'Dolo 650mg' then 142 when 'Telma 40mg' then 0 when 'Azithral 500mg' then 10 else 53 end,case name when 'Augmentin 625mg' then 24 when 'Pantop 40mg' then 86 when 'Dolo 650mg' then 142 when 'Telma 40mg' then 0 when 'Azithral 500mg' then 10 else 53 end,case when name='Telma 40mg' then 'OUT_OF_STOCK' else 'AVAILABLE' end from medicines on conflict(medicine_id,branch_id,batch_number) do update set available_quantity=excluded.available_quantity,received_quantity=excluded.received_quantity,status=excluded.status;
  for i in 1..20 loop insert into sales(branch_id,invoice_number,customer_name,customer_mobile,subtotal,discount,tax,total,payment_method,status) values(b,'DEMO-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(i::text,3,'0'),'Demo Customer '||i,'90000000'||lpad(i::text,2,'0'),50+i*7.5,0,0,50+i*7.5,(array['Cash','UPI','Card'])[((i-1)%3)+1],'COMPLETED') on conflict(invoice_number) do nothing; end loop;
end $$;
